//! Span operation type identifiers generated by Weaver from
//! `model/gen-ai` and `model/mcp` of
//! <https://github.com/open-telemetry/semantic-conventions-genai>,
//! pinned to commit `06ec68e722c45a7218e23ea1bc1339fe4e21ecae`.
//!
//! These are the semconv operation type ids (for example
//! `span.gen_ai.client.inference`), not literal span names: the span name
//! itself is computed at instrumentation time from `{verb} {object}`.
//!
//! DO NOT EDIT. Run `mise run semconv:generate` to regenerate.

/// This span represents a client call to Generative AI model or service that generates a response or requests a tool call based on the input prompt.
///
/// **Span kind** SHOULD be `CLIENT` and MAY be set to `INTERNAL` on spans representing
/// call to models running in the same process. It's RECOMMENDED to use `CLIENT` kind
/// when the GenAI system being instrumented usually runs in a different process than its
/// client or when the GenAI call happens over instrumented protocol such as HTTP
#[allow(dead_code)]
pub const GEN_AI_CLIENT_INFERENCE: &str = "span.gen_ai.client.inference";
/// Describes GenAI agent creation and is usually applicable when working with remote agent services.
///
/// The `gen_ai.operation.name` SHOULD be `create_agent`
#[allow(dead_code)]
pub const GEN_AI_CREATE_AGENT_CLIENT: &str = "span.gen_ai.create_agent.client";
/// Describes GenAI embeddings span - a request to a Generative AI model or service that generates an embeddings based on the input.
///
/// The `gen_ai.operation.name` SHOULD be `embeddings`
#[allow(dead_code)]
pub const GEN_AI_EMBEDDINGS_CLIENT: &str = "span.gen_ai.embeddings.client";
/// Describes tool execution span.
///
/// `gen_ai.operation.name` SHOULD be `execute_tool`.
///
/// GenAI instrumentations that can instrument tool execution calls SHOULD do so,
/// unless another instrumentation can reliably cover all supported tool types.
/// MCP tool executions may also be traced by the
/// [corresponding MCP instrumentation](/docs/gen-ai/mcp.md#client).
///
/// Tools are often executed directly by application code. Application developers
/// are encouraged to follow this semantic convention for tools invoked by their
/// own code and to manually instrument any tool calls that automatic
/// instrumentations do not cover.
///
/// Some tools are specialized, such as [Agent Skills](https://agentskills.io)
/// that agentic frameworks expose as tools. Instrumentations SHOULD distinguish
/// generic tools from specialized ones using framework-specific tool names or
/// other heuristics and record the applicable
/// [refinement](/docs/gen-ai/gen-ai-agent-spans.md#execute-tool-span).
/// They SHOULD NOT record two different spans for one call
#[allow(dead_code)]
pub const GEN_AI_EXECUTE_TOOL_INTERNAL: &str = "span.gen_ai.execute_tool.internal";
/// Describes a request to a Generative AI provider that fetches a previously generated model response by its identifier.
///
/// The `gen_ai.operation.name` SHOULD be `fetch_response`
#[allow(dead_code)]
pub const GEN_AI_FETCH_RESPONSE_CLIENT: &str = "span.gen_ai.fetch_response.client";
