pub const GEN_AI_INVOKE_AGENT_CLIENT: &str = "span.gen_ai.invoke_agent.client";
/// Describes GenAI agent invocation within the same process.
///
/// The `gen_ai.operation.name` SHOULD be `invoke_agent`.
///
/// Examples: LangChain agents, CrewAI agents
#[allow(dead_code)]
pub const GEN_AI_INVOKE_AGENT_INTERNAL: &str = "span.gen_ai.invoke_agent.internal";
/// Represents an operation that executes a coordinated process composed of multiple agents or other operations involving generative AI.
///
/// The `gen_ai.operation.name` SHOULD be `invoke_workflow`.
///
/// The workflow span SHOULD be reported for operations that trigger the execution
/// of composable processes (e.g., graphs, orchestrators) coordinating multiple
/// agents or GenAI calls. It SHOULD NOT be reported for standalone agent invocations.
///
/// The `invoke_workflow` span SHOULD NOT be reported when the workflow invocation is
/// an internal implementation detail of another operation (e.g., an agent or tool that
/// spins up a runner/workflow under the hood to delegate to a sub-agent) rather than
/// a user-facing entry point. Workflows defined by the application SHOULD be reported
/// even when nested, for example a sub-graph invoked as a node of another graph.
///
/// Framework-specific semantic conventions SHOULD define which operations to report
/// as workflows and MAY specify heuristics to distinguish them from standalone
/// agent invocations and internal operations.
///
/// Examples of workflow invocations in different frameworks include:
///
/// - **ADK**: [`Runner.run(...)`](https://adk.dev/workflows/) with multi-agent or graph workflow.
/// - **CrewAI**: [`Crew.kickoff()`](https://docs.crewai.com/concepts/crews)
/// - **LangChain / LangGraph**: [`*Graph*.invoke(...)`](https://reference.langchain.com/python/langgraph/graphs)
/// - **Microsoft Agent Framework**: [`Workflow*.run(...)`](https://learn.microsoft.com/agent-framework/workflows/)
/// - **OpenAI Agents**: [`Runner.run(starting_agent=...)`](https://openai.github.io/openai-agents-python/ref/run/#agents.run.Runner.run) with handoffs, sub-agents, or agents-as-tools
#[allow(dead_code)]
pub const GEN_AI_INVOKE_WORKFLOW_INTERNAL: &str = "span.gen_ai.invoke_workflow.internal";
/// Describes a memory operation, including memory store lifecycle operations and memory record operations.
///
/// The `gen_ai.operation.name` SHOULD be one of `create_memory_store`, `search_memory`, `create_memory`,
/// `update_memory`, `upsert_memory`, `delete_memory`, or `delete_memory_store`.
///
/// `create_memory_store` and `delete_memory_store` cover memory store lifecycle operations.
/// `create_memory`, `update_memory`, `upsert_memory`, `search_memory`, and `delete_memory`
/// cover memory record operations.
///
/// Use `create_memory` when the caller requests creation of new memory records.
/// Use `update_memory` when the caller requests modification of known existing memory records.
/// Use `upsert_memory` when the caller invokes a public API that may create, update, or consolidate
/// memory records without the caller choosing which.
///
/// **Span kind** SHOULD be `CLIENT` and MAY be set to `INTERNAL` on spans representing
/// calls to memory systems running in the same process. It's RECOMMENDED to use `CLIENT` kind
/// when the memory system being instrumented usually runs in a different process than its
/// client or when the memory call happens over instrumented protocol such as HTTP.
///
/// For `delete_memory`, lack of `gen_ai.memory.record.id` may indicate that
/// the operation intends to delete all memory records in the specified store
#[allow(dead_code)]
pub const GEN_AI_MEMORY_CLIENT: &str = "span.gen_ai.memory.client";
/// Represents an agent planning or task decomposition phase.
///
/// The `gen_ai.operation.name` SHOULD be `plan`.
///
/// A plan span represents the decision phase where an agent formulates
/// a strategy before executing it. The LLM call that generates the plan
/// SHOULD be a child of the plan span, and the tool or task spans produced
/// from the plan are typically sibling operations under the same
/// `invoke_agent` span.
///
/// This span SHOULD be reported by instrumentations when they can reliably determine
/// that the operation being instrumented is planning or task decomposition, and SHOULD
/// NOT be reported when the instrumentation cannot distinguish planning from generic
/// reasoning or normal inference
#[allow(dead_code)]
pub const GEN_AI_PLAN_INTERNAL: &str = "span.gen_ai.plan.internal";
/// Describes GenAI retrieval span - a request to a Generative AI service or framework that retrieves relevant information or context from a vector database or search system.
///
/// The `gen_ai.operation.name` SHOULD be `retrieval`
#[allow(dead_code)]
pub const GEN_AI_RETRIEVAL_CLIENT: &str = "span.gen_ai.retrieval.client";
